/**
 * \file widget.h
 * \brief Declaration of the Widget class and helpers.
 *
 * This file holds the public API for widgets. It exists to exercise
 * the \c \file command in every output generator.
 */

#ifndef WIDGET_H
#define WIDGET_H

/**
 * \brief A small widget.
 *
 * Detailed description of Widget. It spans more than one
 * sentence so that the brief and detailed descriptions are
 * clearly distinguishable in every output format.
 */
class Widget {
public:
    /**
     * \brief Resize the widget.
     * \param w The new width in pixels.
     * \param h The new height in pixels.
     * \return True when the resize succeeded, false otherwise.
     */
    bool resize(int w, int h);

    /** \brief Current width. */
    int width;
};

/**
 * \brief Compute the area of a rectangle.
 * \param w Width of the rectangle.
 * \param h Height of the rectangle.
 * \return The computed area.
 */
int rect_area(int w, int h);

#endif
EOF
